// Точное перечисление расстановок флота: корабли не соприкасаются даже углами.
function mkPlacements(L, n) {
  const res = [];
  const add = (cells) => {
    let hl = 0, hh = 0, al = 0, ah = 0;
    for (const c of cells) { if (c < 32) hl |= 1 << c; else hh |= 1 << (c - 32); }
    const halo = new Set();
    for (const c of cells) {
      const r = Math.floor(c / n), q = c % n;
      for (let dr = -1; dr <= 1; dr++) for (let dq = -1; dq <= 1; dq++) {
        const rr = r + dr, qq = q + dq;
        if (rr < 0 || rr >= n || qq < 0 || qq >= n) continue;
        halo.add(rr * n + qq);
      }
    }
    for (const c of halo) { if (c < 32) al |= 1 << c; else ah |= 1 << (c - 32); }
    res.push({ hl, hh, al, ah });
  };
  for (let r = 0; r < n; r++) for (let c = 0; c + L <= n; c++) {
    const cells = []; for (let i = 0; i < L; i++) cells.push(r * n + c + i); add(cells);
  }
  if (L > 1) for (let c = 0; c < n; c++) for (let r = 0; r + L <= n; r++) {
    const cells = []; for (let i = 0; i < L; i++) cells.push((r + i) * n + c); add(cells);
  }
  return res;
}

function count(fleet, n) {
  const fl = [...fleet].sort((a, b) => b - a);
  const tables = new Map();
  for (const L of new Set(fl)) tables.set(L, mkPlacements(L, n));
  let total = 0;
  const k = fl.length;
  function rec(i, haloL, haloH, prevIdx) {
    if (i === k) { total++; return; }
    const T = tables.get(fl[i]);
    const start = (i > 0 && fl[i - 1] === fl[i]) ? prevIdx + 1 : 0;
    for (let j = start; j < T.length; j++) {
      const p = T[j];
      if ((p.hl & haloL) !== 0 || (p.hh & haloH) !== 0) continue;
      rec(i + 1, haloL | p.al, haloH | p.ah, j);
    }
  }
  rec(0, 0, 0, -1);
  return total;
}

if (typeof globalThis.gc === 'function') globalThis.gc();
const cases = [
  [[4,3,3,2],       8], [[4,3,3,2,2],   8], [[4,3,2,2],   8],
  [[4,3,3,2,2,1],   8], [[3,3,2,2],     8], [[5,4,3,3,2], 8],
  [[4,3,3,2],       9], [[4,3,3,2],    10], [[4,3,3,2,2], 9],
];
console.log('флот                 поле   реальностей        клеток  время');
for (const [fleet, n] of cases) {
  const t = Date.now();
  const c = count(fleet, n);
  const cells = fleet.reduce((a, b) => a + b, 0);
  console.log(
    String('[' + fleet.join(',') + ']').padEnd(20),
    (n + 'x' + n).padEnd(6),
    String(c).replace(/\B(?=(\d{3})+(?!\d))/g, ' ').padStart(16),
    String(cells + '/' + n * n).padStart(7),
    String(Date.now() - t) + ' мс'
  );
}
EOF

cd "$TEMP" && node --max-old-space-size=4096 <<'EOF'
const N = 8, SZ = N * N;
const idx = (r, c) => r * N + c;

function mkPlacements(L) {
  const res = [];
  const add = (cells) => {
    let hl = 0, hh = 0, al = 0, ah = 0;
    for (const c of cells) { if (c < 32) hl |= 1 << c; else hh |= 1 << (c - 32); }
    const halo = new Set();
    for (const c of cells) {
      const r = (c / N) | 0, q = c % N;
      for (let dr = -1; dr <= 1; dr++) for (let dq = -1; dq <= 1; dq++) {
        const rr = r + dr, qq = q + dq;
        if (rr >= 0 && rr < N && qq >= 0 && qq < N) halo.add(rr * N + qq);
      }
    }
    for (const c of halo) { if (c < 32) al |= 1 << c; else ah |= 1 << (c - 32); }
    res.push({ hl, hh, al, ah, cells: cells.slice() });
  };
  for (let r = 0; r < N; r++) for (let c = 0; c + L <= N; c++) { const s = []; for (let i = 0; i < L; i++) s.push(idx(r, c + i)); add(s); }
  if (L > 1) for (let c = 0; c < N; c++) for (let r = 0; r + L <= N; r++) { const s = []; for (let i = 0; i < L; i++) s.push(idx(r + i, c)); add(s); }
  return res;
}

const FLEET = [4, 3, 3, 2];
const TAB = new Map(); for (const L of new Set(FLEET)) TAB.set(L, mkPlacements(L));

// История: emptyL/H — заведомо пусто, hullL/H — заведомо корпус, kills — наборы клеток убитых.
function enumerate(hist, want) {
  const { eL, eH, hL, hH, kills } = hist;
  let total = 0;
  const hitCount = new Int32Array(SZ);
  const samples = []; const K = 16; let seen = 0;
  const classes = want && want.cell !== undefined ? new Map() : null;
  const cur = new Array(FLEET.length);
  const killKeys = new Set(kills.map((s) => s.join(',')));

  function leaf(occL, occH) {
    if ((hL & ~occL) !== 0 || (hH & ~occH) !== 0) return; // не покрыт известный корпус
    for (let i = 0; i < FLEET.length; i++) {          // корабль целиком в подбитых клетках -> обязан быть в убитых
      const p = cur[i];
      if ((p.hl & ~hL) === 0 && (p.hh & ~hH) === 0 && !killKeys.has(p.cells.join(','))) return;
    }
    total++;
    for (let c = 0; c < SZ; c++) {
      const bit = c < 32 ? (occL >>> c) & 1 : (occH >>> (c - 32)) & 1;
      if (bit) hitCount[c]++;
    }
    seen++;
    if (samples.length < K) samples.push(cur.map((p) => p.cells));
    else { const j = (Math.random() * seen) | 0; if (j < K) samples[j] = cur.map((p) => p.cells); }
    if (classes) {
      const c = want.cell;
      const bit = c < 32 ? (occL >>> c) & 1 : (occH >>> (c - 32)) & 1;
      let key = 'МИМО';
      if (bit) {
        const ship = cur.find((p) => p.cells.includes(c));
        const allHit = ship.cells.every((x) => x === c || (x < 32 ? (hL >>> x) & 1 : (hH >>> (x - 32)) & 1));
        key = allHit ? 'УБИТ:' + ship.cells.join(',') : 'ПОПАЛ';
      }
      classes.set(key, (classes.get(key) || 0) + 1);
    }
  }

  (function rec(i, occL, occH, haloL, haloH, prev) {
    if (i === FLEET.length) return leaf(occL, occH);
    const T = TAB.get(FLEET[i]);
    const start = i > 0 && FLEET[i - 1] === FLEET[i] ? prev + 1 : 0;
    for (let j = start; j < T.length; j++) {
      const p = T[j];
      if ((p.hl & haloL) | (p.hh & haloH)) continue;
      if ((p.hl & eL) | (p.hh & eH)) continue;
      cur[i] = p;
      rec(i + 1, occL | p.hl, occH | p.hh, haloL | p.al, haloH | p.ah, j);
    }
  })(0, 0, 0, 0, 0, -1);

  return { total, hitCount, samples, classes };
}

const setBit = (m, c) => (c < 32 ? { l: m.l | (1 << c), h: m.h } : { l: m.l, h: m.h | (1 << (c - 32)) });

function play(pick, label) {
  const hist = { eL: 0, eH: 0, hL: 0, hH: 0, kills: [] };
  const fired = new Set();
  let shots = 0, sunk = 0;
  for (;;) {
    const st = enumerate(hist, null);
    if (st.total <= 1) return { shots, sunk, ok: true };
    if (shots > 64) return { shots, sunk, ok: false };
    const cell = pick(st, fired);
    fired.add(cell); shots++;
    const cl = enumerate(hist, { cell }).classes;
    let best = null;                                  // максимально уклончивый ответ
    for (const [k, v] of cl) if (!best || v > best[1]) best = [k, v];
    const [ans] = best;
    if (ans === 'МИМО') { const m = setBit({ l: hist.eL, h: hist.eH }, cell); hist.eL = m.l; hist.eH = m.h; }
    else {
      const m = setBit({ l: hist.hL, h: hist.hH }, cell); hist.hL = m.l; hist.hH = m.h;
      if (ans.startsWith('УБИТ')) {
        const cells = ans.slice(5).split(',').map(Number);
        hist.kills.push(cells.slice().sort((a, b) => a - b)); sunk++;
        for (const c of cells) {                       // ореол убитого — заведомо пусто
          const r = (c / N) | 0, q = c % N;
          for (let dr = -1; dr <= 1; dr++) for (let dq = -1; dq <= 1; dq++) {
            const rr = r + dr, qq = q + dq; if (rr < 0 || rr >= N || qq < 0 || qq >= N) continue;
            const cc = rr * N + qq; if (cells.includes(cc)) continue;
            const e = setBit({ l: hist.eL, h: hist.eH }, cc); hist.eL = e.l; hist.eH = e.h;
          }
        }
      }
    }
  }
}

const smart = (st, fired) => {            // максимум гарантированного схлопывания: p ближе всего к 1/2
  let best = -1, bestScore = -Infinity;
  for (let c = 0; c < SZ; c++) {
    if (fired.has(c)) continue;
    const p = st.hitCount[c] / st.total;
    const s = -Math.abs(p - 0.5);
    if (s > bestScore) { bestScore = s; best = c; }
  }
  return best;
};
const greedy = (st, fired) => {           // классическая плотность: где чаще всего стоит корпус
  let best = -1, bestScore = -Infinity;
  for (let c = 0; c < SZ; c++) { if (fired.has(c)) continue; if (st.hitCount[c] > bestScore) { bestScore = st.hitCount[c]; best = c; } }
  return best;
};
const rand = (st, fired) => { let c; do { c = (Math.random() * SZ) | 0; } while (fired.has(c)); return c; };

const G = 25;
for (const [fn, name] of [[smart, 'МАКС-ЭНТРОПИЯ'], [greedy, 'ПЛОТНОСТЬ'], [rand, 'СЛУЧАЙНО']]) {
  const t = Date.now(); const res = [];
  for (let i = 0; i < G; i++) res.push(play(fn, name));
  const ok = res.filter((r) => r.ok);
  const sh = ok.map((r) => r.shots).sort((a, b) => a - b);
  const avg = (a) => (a.reduce((x, y) => x + y, 0) / a.length).toFixed(1);
  console.log(
    name.padEnd(15),
    'выстрелов сред', avg(sh).padStart(5),
    'мин', String(sh[0]).padStart(3),
    'макс', String(sh[sh.length - 1]).padStart(3),
    '| потоплено к победе', avg(ok.map((r) => r.sunk)), '/ 4',
    '| не сошлось', G - ok.length,
    '|', Date.now() - t, 'мс'
  );
}
EOF

